typedef struct { int fd; int state; void* user_data; } mqtt_session_t;
typedef struct { int topic_id; void (*callback)(void*); } mqtt_subscription_t;

void mqtt_unsubscribe_all(mqtt_session_t* s) { (void)s; }
void mqtt_close_socket(int fd) { (void)fd; }
void mqtt_free_session(mqtt_session_t* s) { (void)s; }
void mqtt_notify_disconnect(mqtt_session_t* s) { (void)s; }
void mqtt_release_observer(mqtt_session_t* s) { (void)s; }

void mqtt_session_destroy(mqtt_session_t* session)
{
  mqtt_release_observer(session);
  mqtt_unsubscribe_all(session);
  mqtt_notify_disconnect(session);
  mqtt_close_socket(session->fd);
  mqtt_free_session(session);
}

